fn public_endpoint(value: &str) -> String {
    if value.trim().is_empty() {
        return String::new();
    }
    let Ok(mut endpoint) = url::Url::parse(value) else {
        return "<invalid>".to_string();
    };
    if !endpoint.username().is_empty() {
        let _ = endpoint.set_username("redacted");
    }
    if endpoint.password().is_some() {
        let _ = endpoint.set_password(Some("redacted"));
    }
    endpoint.set_query(None);
    endpoint.set_fragment(None);
    endpoint.to_string()
}

/// Whether a ureq transport failure came from the response read deadline.
pub fn is_read_timeout(error: &ureq::Error) -> bool {
    let ureq::Error::Transport(transport) = error else {
        return false;
    };
    if transport.kind() != ureq::ErrorKind::Io {
        return false;
    }

    let mut source = transport.source();
    while let Some(error) = source {
        if error.downcast_ref::<io::Error>().is_some_and(is_io_timeout) {
            return true;
        }
        source = error.source();
    }
    false
}

/// Whether a direct response-body read exhausted its socket deadline.
pub fn is_io_timeout(error: &io::Error) -> bool {
    matches!(
        error.kind(),
        io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock
    )
}

/// Classify a failed OpenAI-compatible HTTP call into the shared vocabulary.
pub fn classify_ureq_error(error: ureq::Error) -> ModelFailure {
    let detail = error.to_string();
    match &error {
        ureq::Error::Status(code, _) if *code < 500 => {
            failure(ModelFailureReason::Misconfigured, true, detail)
        }
        ureq::Error::Status(_, _) => failure(ModelFailureReason::Unreachable, true, detail),
        ureq::Error::Transport(_) if is_read_timeout(&error) => {
            failure(ModelFailureReason::Timeout, true, detail)
        }
        ureq::Error::Transport(transport) => {
            let (reason, reachable) = match transport.kind() {
                ureq::ErrorKind::InvalidUrl
                | ureq::ErrorKind::UnknownScheme
                | ureq::ErrorKind::InvalidProxyUrl => (ModelFailureReason::Misconfigured, false),
                ureq::ErrorKind::BadStatus | ureq::ErrorKind::BadHeader => {
                    (ModelFailureReason::BadJson, true)
                }
                ureq::ErrorKind::Io => (ModelFailureReason::Unreachable, true),
                ureq::ErrorKind::Dns
                | ureq::ErrorKind::ConnectionFailed
                | ureq::ErrorKind::InsecureRequestHttpsOnly
                | ureq::ErrorKind::TooManyRedirects
                | ureq::ErrorKind::ProxyConnect
                | ureq::ErrorKind::ProxyUnauthorized
                | ureq::ErrorKind::HTTP => (ModelFailureReason::Unreachable, false),
            };
            failure(reason, reachable, detail)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn failure_reasons_have_stable_serialized_tags() {
        for (reason, tag) in [
            (ModelFailureReason::Unreachable, "unreachable"),
            (ModelFailureReason::Timeout, "timeout"),
            (ModelFailureReason::BadJson, "bad_json"),
            (ModelFailureReason::Misconfigured, "misconfigured"),
        ] {
            assert_eq!(reason.as_str(), tag);
            assert_eq!(
                serde_json::to_string(&reason).unwrap(),
                format!("\"{tag}\"")
            );
        }
    }

    #[test]
    fn provenance_omits_a_reason_only_when_the_model_answered() {
        let model = serde_json::to_value(ModelCallProvenance::model()).unwrap();
        assert_eq!(model["source"], "model");
        assert!(model.get("fallback_reason").is_none());

        let fallback =
            serde_json::to_value(ModelCallProvenance::fallback(ModelFailureReason::Timeout))
                .unwrap();
        assert_eq!(fallback["source"], "fallback");
        assert_eq!(fallback["fallback_reason"], "timeout");
    }

    #[test]
    fn health_constructors_distinguish_absent_healthy_and_failed_models() {
        let absent = ModelHealth::not_configured("", "");
        assert!(!absent.configured);
        assert_eq!(absent.failure_reason, None);

        let healthy = ModelHealth::healthy("http://localhost/v1", "model");
        assert!(healthy.configured);
        assert!(healthy.reachable);
        assert!(healthy.responds_json);

        let failure = failure(ModelFailureReason::BadJson, true, "not json");
        let failed = ModelHealth::failed("http://localhost/v1", "model", &failure);
        assert!(failed.configured);
        assert!(failed.reachable);
        assert!(!failed.responds_json);
        assert_eq!(failed.failure_reason, Some(ModelFailureReason::BadJson));
    }

    #[test]
    fn health_never_exposes_endpoint_credentials_or_query_secrets() {
        let endpoint = "http://user:secret@example.test/v1?token=hidden#fragment";
        let failure = failure(
            ModelFailureReason::Unreachable,
            false,
            format!("could not reach {endpoint}"),
        );

        let health = ModelHealth::failed(endpoint, "model", &failure);
        let serialized = serde_json::to_string(&health).unwrap();

        assert!(health.base_url.contains("redacted:redacted"));
        assert!(!serialized.contains("secret"));
        assert!(!serialized.contains("hidden"));
        assert!(!serialized.contains("fragment"));
    }

    #[test]
    fn http_rejection_is_misconfigured_while_server_failure_is_unavailable() {
        let client_error = classify_ureq_error(ureq::Error::Status(
            404,
            ureq::Response::new(404, "Not Found", "body").unwrap(),
        ));
        assert_eq!(client_error.reason, ModelFailureReason::Misconfigured);
        assert!(client_error.reachable);

        let server_error = classify_ureq_error(ureq::Error::Status(
            500,
            ureq::Response::new(500, "Error", "body").unwrap(),
        ));
        assert_eq!(server_error.reason, ModelFailureReason::Unreachable);
        assert!(server_error.reachable);
    }

    #[test]
    fn direct_io_timeouts_share_the_timeout_classifier() {
        for kind in [io::ErrorKind::TimedOut, io::ErrorKind::WouldBlock] {
            assert!(is_io_timeout(&io::Error::new(kind, "slow body")));
        }
        assert!(!is_io_timeout(&io::Error::new(
            io::ErrorKind::ConnectionRefused,
            "absent"
        )));
    }
}
